"""Escaped server-rendered owner UI; no synthetic outcomes or inline execution."""
from html import escape
import json

SECTIONS=[('overview','Founder overview','نمای کلی','01'),('system','System map','نقشه سامانه','02'),('agents','Agent command','نقش‌های تخصصی','03'),('connections','Connectivity atlas','اطلس اتصال‌ها','04'),('missions','Mission control','کنترل مأموریت','05'),('opportunities','Opportunity intelligence','هوشمندی فرصت‌ها','06'),('finance','Financial intelligence','هوشمندی مالی','07'),('knowledge','Knowledge & research','دانش و پژوهش','08'),('security','Operations & security','عملیات و امنیت','09'),('journey','Historical journey','مسیر توسعه','10'),('decisions','Decision centre','مرکز تصمیم','11'),('reports','Reports','گزارش‌ها','12')]

def e(value):return escape(str(value),quote=True)
def t(en,fa):return '<span lang="en">'+e(en)+'</span><span lang="fa">'+e(fa)+'</span>'
def val(value):
    if value is None:return t('Not recorded','ثبت نشده')
    return e(json.dumps(value,ensure_ascii=False)) if isinstance(value,(dict,list)) else e(value)
def records(value):
    if isinstance(value,list):return value
    if isinstance(value,dict):return [{'id':k,'value':v} for k,v in value.items()]
    return []
def badge(status):
    raw=str(status or 'NOT_RECORDED');colour='good' if raw in {'VERIFIED','VERIFIED_OFFLINE','LIVE_VERIFIED','VERIFIED_LIVE','COMPLETE'} else 'bad' if raw in {'FAILED','DENIED','DEAD','RETRY_EXHAUSTED'} else 'pending'
    return '<span class="badge '+colour+'">'+e(raw.replace('_',' '))+'</span>'
def detail(value,label=None):return '<details class="evidence technical"><summary>'+(label or t('Inspect source record','مشاهده رکورد منبع'))+'</summary><pre dir="auto">'+e(json.dumps(value,indent=2,ensure_ascii=False))+'</pre></details>'
def empty():return '<div class="empty">'+t('No records available for this view.','رکوردی برای این بخش در دسترس نیست.')+'</div>'
def note(en,fa):return '<div class="section-note">'+t(en,fa)+'</div>'
def cards(values,kind='record'):
    output=[]
    for r in records(values):
        if not isinstance(r,dict):r={'value':r}
        title=next((r[k] for k in ('name','title','label','trace_id','id','provider_id') if r.get(k) is not None),'Recorded item')
        description=next((r[k] for k in ('description','reason','limitation','capability','next_action') if r.get(k)),None)
        fields=''.join('<div><dt>'+e(k.replace('_',' '))+'</dt><dd dir="auto">'+val(r[k])+'</dd></div>' for k in ('source','source_url','timestamp','retrieved_at','verification','confidence','source_gap','completed_jobs','receipt_seq') if k in r)
        output.append('<article class="record '+kind+'"><div class="record-top"><h3 dir="auto">'+e(title)+'</h3>'+badge(r.get('status',r.get('state')))+'</div>'+('<p dir="auto">'+val(description)+'</p>' if description else '')+('<dl class="record-meta">'+fields+'</dl>' if fields else '')+detail(r)+'</article>')
    return ''.join(output) or empty()
def metric(r):
    denominator=(' / '+val(r['denominator'])) if r.get('denominator') is not None else ''
    return '<article class="metric"><div class="metric-label">'+e(r.get('label',r.get('id','Recorded metric')))+'</div><strong class="metric-value" dir="auto">'+val(r.get('value'))+denominator+'</strong>'+badge(r.get('verification'))+'<details class="metric-proof"><summary>'+t('Source & limitations','منبع و محدودیت‌ها')+'</summary><dl>'+''.join('<dt>'+e(k)+'</dt><dd>'+val(r.get(k))+'</dd>' for k in ('source','timestamp','freshness','confidence'))+'</dl></details></article>'
def reports(values):
    out=[]
    for r in records(values):
        out.append('<article class="record"><div class="record-top"><div><div class="eyebrow">'+t('Persisted research packet','بسته پژوهشی ثبت‌شده')+'</div><h3>'+e(r.get('trace_id','Not recorded'))+'</h3></div>'+badge(r.get('status'))+'</div><div class="report-facts"><div>'+t('Unverified candidates','نامزدهای تأییدنشده')+'<strong>'+val(r.get('unverified_candidates'))+'</strong></div><div>'+t('Excluded','کنار گذاشته‌شده')+'<strong>'+val(r.get('excluded'))+'</strong></div><div>'+t('Journal receipt','رسید دفتر')+'<strong>'+val(r.get('ledger_seq'))+'</strong></div></div><p class="muted">'+t('Counts are per packet and may overlap. They are not qualified demand or income.','شمارش مربوط به هر بسته است و ممکن است هم‌پوشانی داشته باشد؛ تقاضای تأییدشده یا درآمد نیست.')+'</p><details><summary>'+t('Evidence and next action','شواهد و اقدام بعدی')+'</summary><p dir="auto">'+val(r.get('next_internal_action'))+'</p>'+detail(r.get('sources',[]),t('Source receipts','رسیدهای منبع'))+'</details>'+detail(r)+'</article>')
    return ''.join(out) or empty()

def render(data,reports_only=False):
    product=data.get('product',{}) if isinstance(data.get('product'),dict) else {}
    provider_data=data.get('providers',{})
    providers=records(provider_data.get('providers',[]))+records(provider_data.get('additional_adapters',[])) if isinstance(provider_data,dict) else []
    adapted=[]
    for p in providers:
        p=dict(p);p['name']=p.get('provider_id','Unknown');p['status']=p.get('connection_status',p.get('last_observed_state',p.get('implementation_state')));p['description']=p.get('capabilities',p.get('capability'));adapted.append(p)
    metrics='<div class="metrics">'+''.join(metric(m) for m in records(product.get('metrics',[])))+'</div>'
    if not product.get('metrics'):metrics=empty()
    sections={}
    sections['overview']='<div class="briefing"><div><div class="eyebrow">'+t('Executive briefing','خلاصه مدیریتی')+'</div><h2>'+t('Evidence first. Every step visible.','شواهد در اولویت؛ هر گام قابل مشاهده.')+'</h2><p>'+t('Understand what works, what remains unproven and the next decision that matters.','آنچه کار می‌کند، آنچه هنوز اثبات نشده و تصمیم مهم بعدی را ببینید.')+'</p></div><div class="briefing-state">'+badge(data.get('full_acceptance','OPEN'))+'<p>'+t('This screen alone does not establish production acceptance.','این صفحه به‌تنهایی تأیید بهره‌برداری عملیاتی نیست.')+'</p></div></div>'+metrics+'<div class="two-col"><article class="callout"><h3>'+t('What the records prove','آنچه رکوردها اثبات می‌کنند')+'</h3><p>'+val(product.get('journey',{}).get('works'))+'</p><a href="#knowledge">'+t('Explore research evidence →','مشاهده شواهد پژوهشی ←')+'</a></article><article class="callout warning"><h3>'+t('What needs attention','آنچه به توجه نیاز دارد')+'</h3><p>'+val(product.get('journey',{}).get('blocked'))+'</p><a href="#decisions">'+t('Review next decisions →','بررسی تصمیم‌های بعدی ←')+'</a></article></div>'
    sections['system']=note('Expand a plane to inspect its recorded contracts, dependencies and limits.','هر لایه را برای بررسی قراردادها، وابستگی‌ها و محدودیت‌های ثبت‌شده باز کنید.')+cards(product.get('layers',[]),'layer')
    sections['agents']=note('18 specialist slots remain binding. A role definition is not proof of an operational agent.','۱۸ جایگاه تخصصی همچنان الزام‌آورند. تعریف نقش، اثبات عامل عملیاتی نیست.')+cards(product.get('roles',[]))
    sections['connections']=note('Only installed adapter records are counted below. The founder target remains 130; unresolved inventory entries are not invented.','فقط رکوردهای آداپتور نصب‌شده شمرده می‌شوند. هدف بنیان‌گذار ۱۳۰ است؛ جایگاه‌های نامشخص جعل نشده‌اند.')+'<div class="inline-stats"><span>'+t('Observed catalog','فهرست مشاهده‌شده')+': <b>'+str(len(adapted))+'</b></span><span>'+t('Founder target','هدف بنیان‌گذار')+': <b>130</b></span></div>'+cards(adapted)+detail(product.get('provider_inventory',{}),t('Inventory provenance','منشأ فهرست'))
    sections['missions']='<div class="two-col"><article class="callout"><h3>'+t('Worker observation','مشاهده worker')+'</h3>'+badge(data.get('worker',{}).get('state'))+detail(data.get('worker',{}))+'</article><article class="callout warning"><h3>'+t('Emergency stop','توقف اضطراری')+'</h3><p>'+t('Read-only interface. No stop action has been sent here. Use the authenticated operational control path.','رابط فقط خواندنی است؛ فرمان توقفی از اینجا ارسال نشده. از مسیر احرازشده کنترل عملیاتی استفاده کنید.')+'</p><code>apex stop --level STOP_EXECUTION</code></article></div><h3 class="subheading">'+t('Mission graphs','گراف مأموریت‌ها')+'</h3>'+cards(data.get('missions',[]))+'<h3 class="subheading">'+t('Durable schedules','زمان‌بندی پایدار')+'</h3>'+cards(data.get('schedules',[]))+detail(data.get('queue',{}),t('Queue and attempt records','صف و رکورد تلاش‌ها'))
    sections['opportunities']=note('Research packets retain uncertainty. Review eligibility, deadlines and primary sources before acting.','عدم‌قطعیت بسته‌ها حفظ شده است. پیش از اقدام، صلاحیت، مهلت و منابع اولیه را بررسی کنید.')+reports(data.get('reports',[]))
    sections['finance']='<article class="callout warning"><h3>'+t('Opportunity value is not earned income','ارزش فرصت، درآمد کسب‌شده نیست')+'</h3><p>'+t('Revenue, received payments and profit are not inferred from tender values or research activity.','از مبلغ مناقصه یا پژوهش، درآمد، وجه دریافتی یا سود استنباط نمی‌شود.')+'</p>'+badge(data.get('financial_outcome'))+'</article>'+metrics+detail({k:data.get(k) for k in ('financial_outcome','recorded_field_api_spend_pence','independent_improvement')})
    sections['knowledge']=note('A receipt proves a recorded exchange, not scientific truth, customer demand or founder suitability.','رسید، تبادل ثبت‌شده را اثبات می‌کند؛ نه حقیقت علمی، تقاضای مشتری یا تناسب با بنیان‌گذار را.')+cards(product.get('research',[]))
    sections['security']=note('No credential values are displayed. Tunnel process status is separate from routing, owner authorization and HTTPS.','هیچ مقدار محرمانه‌ای نمایش داده نمی‌شود. وضعیت فرایند تونل با مسیریابی، دسترسی مالک و HTTPS متفاوت است.')+cards(product.get('acceptance',[]))+detail({k:data.get(k) for k in ('runtime_service','remote_https','full_acceptance','private_provider_authorization','audit_events_verified')})
    sections['journey']='<label class="search"><span>'+t('Search the recorded timeline','جست‌وجوی رویدادهای ثبت‌شده')+'</span><input id="timeline-search" type="search" autocomplete="off" placeholder="Commit, trace, event…" aria-label="Search timeline"></label><div id="timeline-records">'+cards(product.get('timeline',[]),'timeline-event')+'</div><p id="timeline-empty" hidden>'+t('No matching recorded events.','رویداد مطابقی یافت نشد.')+'</p>'
    sections['decisions']=note('Only evidence-grounded decisions are shown. An authorization request is not proof of consent.','فقط تصمیم‌های مبتنی بر شواهد نمایش داده می‌شوند. درخواست دسترسی، به‌معنای دریافت رضایت نیست.')+cards(product.get('decisions',[]))
    sections['reports']='<div class="report-header"><p>'+t('Persisted operational evidence. Summaries are not measured external outcomes.','شواهد عملیاتی ثبت‌شده؛ خلاصه‌ها نتیجه خارجی اندازه‌گیری‌شده نیستند.')+'</p><a class="button secondary" href="/reports.json" download="apex-reports.json">'+t('Export recorded reports','دریافت گزارش‌های ثبت‌شده')+'</a></div>'+reports(data.get('reports',[]))
    nav=''.join('<a href="#'+key+'" data-section="'+key+'"><span class="nav-number">'+num+'</span>'+t(en,fa)+'</a>' for key,en,fa,num in SECTIONS)
    sections['connections'] += '<p><a href="/connections/google">'+t('Google connection and consent','اتصال و رضایت Google')+'</a></p>'
    panels=''.join('<section class="panel" id="'+key+'" aria-labelledby="heading-'+key+'"><div class="section-heading"><span class="section-number">'+num+'</span><h2 id="heading-'+key+'">'+t(en,fa)+'</h2></div>'+sections[key]+'</section>' for key,en,fa,num in SECTIONS)
    return ('<!doctype html><html lang="en" dir="ltr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="color-scheme" content="light dark"><meta name="apple-mobile-web-app-capable" content="yes"><meta name="apple-mobile-web-app-title" content="APEX"><meta name="referrer" content="no-referrer"><title>APEX · '+('Reports' if reports_only else 'Founder Command Centre')+'</title><link rel="stylesheet" href="/assets/console.css"><script defer src="/assets/console.js"></script></head><body data-initial="'+('reports' if reports_only else 'overview')+'"><a class="skip" href="#main">'+t('Skip to content','رفتن به محتوا')+'</a><aside class="sidebar"><a class="brand" href="/console"><span class="brand-symbol" aria-hidden="true">A</span><span>APEX<small>'+t('INTELLIGENCE CORE','هسته هوشمندی')+'</small></span></a><div class="sidebar-caption">'+t('FOUNDER WORKSPACE','فضای کاری بنیان‌گذار')+'</div><nav aria-label="Main navigation">'+nav+'</nav><div class="sidebar-foot"><span class="status-dot"></span>'+t('Evidence-led · acceptance open','مبتنی بر شواهد · پذیرش باز')+'</div></aside><div class="workspace"><header class="topbar"><div><div class="eyebrow">'+t('Owner command','فرمان مالک')+'</div><span class="topbar-title">'+t('Clarity before action','شفافیت پیش از اقدام')+'</span></div><div class="toolbar"><button type="button" id="language" aria-label="Change language">فارسی / EN</button><button type="button" id="theme" aria-label="Change appearance">'+t('Appearance','ظاهر')+'</button><button type="button" id="detail-mode" aria-pressed="false">'+t('Technical details','جزئیات فنی')+'</button><button type="button" id="refresh">'+t('Refresh','تازه‌سازی')+'</button></div></header><main id="main" tabindex="-1"><div class="workspace-context"><span class="badge pending">'+t('Read-only evidence view','نمای خواندنی شواهد')+'</span><span>'+t('Source: durable APEX journal','منبع: دفتر پایدار APEX')+'</span></div>'+panels+'<footer><span>'+t('Original mandate preserved. No outcome inferred from configuration.','منشور اصلی محفوظ است؛ از پیکربندی نتیجه‌ای استنباط نمی‌شود.')+'</span><span dir="auto">'+e(product.get('commit','Commit not supplied'))+'</span></footer></main></div></body></html>').encode('utf-8')
